package enc

// Psychoacoustic model 2 geometry and constants, formula-derived and
// generated as exact hex float64 literals by a throwaway scratchpad
// program (never committed): partitions of at most 1/3 Bark over FFT
// lines 0..512 (Zwicker Bark scale), per-partition absolute threshold
// from the Terhardt formula clamped at +70 dB and anchored to the
// full-scale-sine = 96 dB SPL convention, and the Schroeder spreading
// function with the ISO model 2 correction term (all formulas as
// published in Painter/Spanias; no codec source consulted). The
// committed literals are the runtime truth; psymodel_test.go validates
// structure and values and freezes sha256 checksums.

